 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    marker = min(counts, key=lambda c: counts[c])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    base = max((v for v in counts if v != marker), key=lambda v: counts[v])
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    shape = [(r-r0, c-c0) for r, c in points]
    out = [row[:] for row in grid]
    sh, sw = max(r for r, c in shape)+1, max(c for r, c in shape)+1
    for dr in range(h-sh+1):
        for dc in range(w-sw+1):
            cells = [(dr+r, dc+c) for r, c in shape]
            if all(grid[r][c] == base for r, c in cells):
                for r, c in cells:
                    out[r][c] = marker
    return out


if __name__ == '__main__':
    pass
